  ('5f1e2d3c-0028-4a00-8000-000000000001', '3.1', 'Approche de l’analyse métier', 'Business Analysis Approach',
   '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Les textes en italique sont des aides : remplacez-les par votre contenu ou effacez-les.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Objet et contexte"}]},{"type":"paragraph","content":[{"type":"text","text":"Résumez le changement visé par l’initiative et ce que le travail d’analyse doit lui apporter.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Démarche retenue"}]},{"type":"paragraph","content":[{"type":"text","text":"Indiquez si l’analyse sera menée de façon prédictive, adaptative ou mixte, et ce qui justifie ce choix : degré d’incertitude, rythme des livraisons, contraintes réglementaires.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Activités et livrables prévus"}]},{"type":"paragraph","content":[{"type":"text","text":"Listez les principales activités d’analyse, ce qu’elles produiront, qui les mène et pour quand.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Activité"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Livrable attendu"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Responsable"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Échéance"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph"}]},{"type":"tableCell","content":[{"type":"paragraph"}]},{"type":"tableCell","content":[{"type":"paragraph"}]},{"type":"tableCell","content":[{"type":"paragraph"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Niveau de formalisme"}]},{"type":"paragraph","content":[{"type":"text","text":"Précisez le degré de détail attendu pour les exigences et la documentation, et ce qui doit être approuvé formellement.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Liens avec les autres approches"}]},{"type":"paragraph","content":[{"type":"text","text":"Indiquez où se trouvent l’engagement des parties prenantes, la gouvernance et la gestion de l’information ; vous pouvez les rédiger dans des sous-pages de celle-ci.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hypothèses et points ouverts"}]},{"type":"paragraph","content":[{"type":"text","text":"Notez les hypothèses sur lesquelles repose cette approche. Une question qui attend une réponse peut devenir un ticket Question.","marks":[{"type":"italic"}]}]}]}'::jsonb,
