  ('5f1e2d3c-0028-4a00-8000-000000000004', '3.4', 'Approche de la gestion de l’information', 'Information Management Approach',
   '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Les textes en italique sont des aides : remplacez-les par votre contenu ou effacez-les.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Organisation de l’information"}]},{"type":"paragraph","content":[{"type":"text","text":"Décrivez comment l’information de l’initiative est rangée : arborescence des pages, conventions de titre, usage des Epics pour regrouper les tickets.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Niveau de détail"}]},{"type":"paragraph","content":[{"type":"text","text":"Précisez le niveau de détail attendu selon le type d’information et selon ses lecteurs.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Traçabilité"}]},{"type":"paragraph","content":[{"type":"text","text":"Indiquez quels liens sont tenus systématiquement (besoin et exigence, exigence et page de conception, exigence et ticket) et qui les tient à jour.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Accès et confidentialité"}]},{"type":"paragraph","content":[{"type":"text","text":"Précisez qui doit pouvoir lire ou modifier l’information, et quelles informations sensibles demandent une attention particulière.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Conservation et réutilisation"}]},{"type":"paragraph","content":[{"type":"text","text":"Notez ce qui doit pouvoir resservir après l’initiative, sous quelle forme et où cela sera conservé.","marks":[{"type":"italic"}]}]}]}'::jsonb,
