  ('5f1e2d3c-0028-4a00-8000-000000000007', '4.2', 'Résultats d’élicitation', 'Elicitation Results',
   '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Les textes en italique sont des aides : remplacez-les par votre contenu ou effacez-les.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Activité"}]},{"type":"paragraph","content":[{"type":"text","text":"Indiquez la date, la technique, les participants et la référence de la page du plan d’activités d’élicitation, s’il y en a une.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ce qui a été recueilli"}]},{"type":"paragraph","content":[{"type":"text","text":"Consignez ce qui a été dit, montré ou observé, sans l’interpréter encore. Précisez qui l’a exprimé quand c’est utile.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Besoins et exigences pressentis"}]},{"type":"paragraph","content":[{"type":"text","text":"Notez les besoins et les exigences qui se dégagent. Une fois créés dans ACTA, citez leurs références ici et liez-les à cette page.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Questions ouvertes"}]},{"type":"paragraph","content":[{"type":"text","text":"Notez ce qui reste à éclaircir. Une question qui attend une réponse peut devenir un ticket Question.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Confirmation"}]},{"type":"paragraph","content":[{"type":"text","text":"Vérifiez ces résultats auprès des participants ou en les recoupant avec d’autres sources. Pour les confirmer, déclarez une version de la page, en indiquant dans sa note qui a confirmé et comment.","marks":[{"type":"italic"}]}]}]}'::jsonb,
   '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Text in italics is guidance: replace it with your own content or delete it.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Activity"}]},{"type":"paragraph","content":[{"type":"text","text":"State the date, the technique, the participants and the reference of the elicitation activity plan page, if there is one.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What was captured"}]},{"type":"paragraph","content":[{"type":"text","text":"Record what was said, shown or observed, without interpreting it yet. Note who expressed it where useful.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Emerging needs and requirements"}]},{"type":"paragraph","content":[{"type":"text","text":"Note the needs and requirements that emerge. Once they exist in ACTA, quote their references here and link them to this page.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Open questions"}]},{"type":"paragraph","content":[{"type":"text","text":"Note what still needs clarifying. A question awaiting an answer can become a Question ticket.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Confirmation"}]},{"type":"paragraph","content":[{"type":"text","text":"Check these results with the participants or against other sources. To confirm them, declare a version of the page, stating in its note who confirmed and how.","marks":[{"type":"italic"}]}]}]}'::jsonb, 'delivered'),
